fn largest_power_of_two_le(n: i8) -> i8 {
    // Find the largest power of two z such that 1 ≤ z ≤ n.
    // We start from z = 1 and keep doubling while z ≤ n/2.
    let mut z: i8 = 1;
    // Since n is positive, n >> 1 is floor(n/2). We can safely
    // check z ≤ n/2 without worrying about z << 1 overflowing:
    // once z > n/2, doubling z would exceed n.
    while z <= (n >> 1) {
        z <<= 1;
    }
    z
}

fn solve(n: i8) -> i8 {
    // n is guaranteed to be at least 1.
    if n % 2 != 0 {
        // If n is odd: (n - 1) / 2
        (n - 1) / 2
    } else {
        // If n is even: subtract the largest power of two ≤ n, then halve
        let z = largest_power_of_two_le(n);
        (n - z) / 2
    }
}

